import type { BffNormalizedData } from 'services/BffService/BffService';

import { bffApi } from '../bffApi';
import type {
  BigNumbersViewData,
  BrandPowerExportArgs,
  CategoryExportData,
  CountriesBrandPowerExportArgs,
  CountriesBrandPowerExportResponse,
  CountryBrandBreakdownData,
  CountryExportData,
  CountryOverviewData,
  CountrySummaryPowerData,
  ProcessedViewResult,
  RawCategoryExportData,
  RawCountryExportData,
  ZonePerformanceViewData,
} from './powerBookExport.types';

function normalizeView<T = BffNormalizedData>(view: ProcessedViewResult): T {
  return view.components.reduce<Record<string, Record<string, unknown>>>(
    (acc, component) => {
      acc[component.id] = component.data ?? {};
      return acc;
    },
    {},
  ) as T;
}

function normalizeCategory(raw: RawCategoryExportData): CategoryExportData {
  return {
    zonePerformance: normalizeView<ZonePerformanceViewData>(
      raw.zonePerformance,
    ),
    bigNumbers: normalizeView<BigNumbersViewData>(raw.bigNumbers),
    maturityPerformance: normalizeView(raw.maturityPerformance),
    zonePerformanceDetails: normalizeView(raw.zonePerformanceDetails),
    ...(raw.topCountryContribution && {
      topCountryContribution: normalizeView(raw.topCountryContribution),
    }),
    ...(raw.trendPowerEvolution && {
      trendPowerEvolution: normalizeView(raw.trendPowerEvolution),
    }),
  };
}

function normalizeCountry(raw: RawCountryExportData): CountryExportData {
  return {
    overview: normalizeView<CountryOverviewData>(raw.overview),
    overviewMegabrands: normalizeView<CountryOverviewData>(
      raw.overviewMegabrands,
    ),
    abiBrandBreakdown: normalizeView<CountryBrandBreakdownData>(
      raw.abiBrandBreakdown,
    ),
    competitorBrandBreakdown: normalizeView<CountryBrandBreakdownData>(
      raw.competitorBrandBreakdown,
    ),
    summaryPower: normalizeView<CountrySummaryPowerData>(raw.summaryPower),
  };
}

const powerBookExportApi = bffApi.injectEndpoints({
  endpoints: (builder) => ({
    getExportGroup: builder.query<
      Record<string, CategoryExportData>,
      BrandPowerExportArgs
    >({
      query: (args) => ({
        endpoint: '/power-book/export',
        method: 'POST' as const,
        body: {
          categories: args.categories,
          period: args.period,
        },
        dt_end: args.dt_end,
      }),
      transformResponse: (raw: Record<string, RawCategoryExportData>) =>
        Object.fromEntries(
          Object.entries(raw).map(([name, cat]) => [
            name,
            normalizeCategory(cat),
          ]),
        ),
    }),

    getCountriesExport: builder.query<
      CountriesBrandPowerExportResponse,
      CountriesBrandPowerExportArgs
    >({
      query: (args) => ({
        endpoint: '/power-book/export/countries',
        method: 'POST' as const,
        body: {
          countries: args.countries,
          periods: args.periods,
        },
        dt_end: args.dt_end,
      }),
      transformResponse: (
        raw: Record<string, Record<string, RawCountryExportData>>,
      ) => {
        const result: CountriesBrandPowerExportResponse = {};
        for (const key of Object.keys(raw)) {
          if (key !== 'QTD' && key !== 'YTD') continue;
          const normalized: Record<string, CountryExportData> = {};
          for (const [country, data] of Object.entries(raw[key])) {
            normalized[country] = normalizeCountry(data);
          }
          result[key] = normalized;
        }
        return result;
      },
    }),
  }),
});

export const { useGetExportGroupQuery, useGetCountriesExportQuery } =
  powerBookExportApi;
